'use strict';
// Lern-Survivor – Physik Klasse 7, LB 1 Kräfte (Gymnasium Sachsen). Quellen: OPAL „Physik Klasse 7 – GDP“
// (Schülerseiten lb1-01 bis lb1-09, Steckbriefe, „Rechnen Schritt für Schritt“), Lehrplan Gymnasium Physik Kl. 7 LB 1.
// Kursfestlegungen: g = 10 N/kg (Mond 1,6 N/kg), Hebel ohne Umstellen, nur Haft- und Gleitreibung, keine Reibungszahl,
// Nordpol rot / Südpol grün. Formeln: $…$ (kursiv, F_G = Index), Brüche: {{Zähler|Nenner}}.
(window.KURS = window.KURS || {}).kraefte = {
  stufe: 'Kl. 7 · LB 1: Kraft, Kraftpfeil, Gewichtskraft, Hooke, Hebel, Reibung, Magnete, Ladung',
  fragen: [
    // ---------- 1 Die Kraft und ihre Wirkungen ----------
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Woran erkennt man, dass eine Kraft wirkt?', a: ['An ihrer Wirkung auf einen Körper', 'Man sieht die Kraft direkt', 'Am Geräusch, das sie macht', 'Daran, dass der Körper warm wird'], e: 'Eine Kraft selbst sieht man nicht. Man sieht nur, was sie bewirkt.', src: 'OPAL Ph7 1'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Welche zwei Wirkungen kann eine Kraft haben?', a: ['Bewegung ändern oder Form ändern', 'Masse ändern oder Farbe ändern', 'Stoff ändern oder Masse ändern', 'Temperatur ändern oder Stoff ändern'], e: 'Ein Körper wird schneller, langsamer oder ändert die Richtung – oder er wird eingedrückt, gedehnt, verbogen.', src: 'OPAL Ph7 1'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'In welcher Einheit gibt man Kräfte an?', a: ['Newton (N)', 'Kilogramm (kg)', 'Meter (m)', 'Gramm (g)'], e: 'Die Einheit der Kraft ist das Newton, Zeichen N.', src: 'OPAL Ph7 1 Steckbrief'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Mit welchem Gerät misst man Kräfte?', a: ['Kraftmesser', 'Balkenwaage', 'Lineal', 'Thermometer'], e: 'Im Kraftmesser (Federkraftmesser) steckt eine Feder, die sich unter der Kraft dehnt.', src: 'OPAL Ph7 1 Steckbrief'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Welches Formelzeichen hat die Kraft?', a: ['$F$', '$m$', '$K$', 'N'], e: '$F$ kommt vom englischen „force“. N ist die Einheit, kein Formelzeichen.', src: 'OPAL Ph7 1 Steckbrief'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Knete wird zusammengedrückt. Welche Wirkung hat die Kraft?', a: ['Formänderung', 'Bewegungsänderung', 'Keine Wirkung', 'Massenänderung'], e: 'Die Knete wird eingedrückt – ihre Form ändert sich.', src: 'OPAL Ph7 1'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Ein Fahrrad bremst. Welche Wirkung hat die Kraft?', a: ['Bewegungsänderung', 'Formänderung', 'Keine Wirkung', 'Massenänderung'], e: 'Das Fahrrad wird langsamer – seine Bewegung ändert sich.', src: 'OPAL Ph7 1'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Ein Gummiband wird gedehnt. Welche Wirkung hat die Kraft?', a: ['Formänderung', 'Bewegungsänderung', 'Keine Wirkung', 'Massenänderung'], e: 'Das Gummiband wird länger – seine Form ändert sich.', src: 'OPAL Ph7 1'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Zwischen wie vielen Körpern wirkt eine Kraft immer?', a: ['Zwischen zwei Körpern', 'Nur an einem Körper', 'Zwischen drei Körpern', 'Das ist ganz beliebig'], e: 'Frag immer: Wer übt die Kraft aus – und auf wen?', src: 'OPAL Ph7 1'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Rechne um: 2,5 kN = ?', a: ['2500 N', '250 N', '25 N', '25 000 N'], e: '1 kN = 1000 N, also 2,5 · 1000 N = 2500 N.', src: 'OPAL Ph7 1'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Rechne um: 4500 N = ?', a: ['4,5 kN', '45 kN', '0,45 kN', '450 kN'], e: '4500 N : 1000 = 4,5 kN.', src: 'OPAL Ph7 1'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Etwa welche Gewichtskraft hat eine Tafel Schokolade (100 g)?', a: ['1 N', '100 N', '10 N', '0,1 N'], e: '100 g = 0,1 kg, und 1 kg hat etwa 10 N – also etwa 1 N.', src: 'OPAL Ph7 1 Steckbrief'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 2, q: 'Ein Fußball wird per Kopfball abgelenkt, bleibt aber gleich schnell. Was hat die Kraft geändert?', a: ['Die Bewegung, denn die Richtung ändert sich', 'Nichts, denn er bleibt ja gleich schnell', 'Nur die Form, denn der Ball wird eingedrückt', 'Die Masse, denn der Ball wird leichter'], e: 'Auch eine Richtungsänderung ist eine Änderung der Bewegung.', src: 'OPAL Ph7 1 Falle'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 2, q: 'Ein Fuß tritt gegen einen Ball. Welche Aussage stimmt?', a: ['Der Fuß wirkt auf den Ball und der Ball auf den Fuß.', 'Nur der Fuß wirkt auf den Ball, nicht umgekehrt.', 'Nur der Ball wirkt auf den Fuß, nicht umgekehrt.', 'Auf den Fuß wirkt gar keine Kraft, nur auf den Ball.'], e: 'Zwei Körper wirken immer gegenseitig aufeinander – das spürst du an den Zehen.', src: 'OPAL Ph7 1'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 2, q: 'Welcher Satz ist physikalisch richtig?', a: ['Er kann eine große Kraft auf die Hantel ausüben.', 'Er hat sehr viel Kraft in seinen Armen.', 'Beim Heben verbraucht er seine ganze Kraft.', 'Nach dem Training ist seine Kraft aufgebraucht.'], e: 'Kraft ist kein Vorrat, den man „hat“. Sie wirkt immer zwischen zwei Körpern.', src: 'OPAL Ph7 1 Falle'},

    // ---------- 2 Kraftpfeil und Kräfte addieren ----------
    {t: '2 Kraftpfeil und Kräfte addieren', d: 1, q: 'Welche drei Angaben beschreiben eine Kraft vollständig?', a: ['Betrag, Richtung und Angriffspunkt', 'Masse, Länge und Zeit', 'Betrag, Farbe und Material', 'Richtung, Masse und Tempo'], e: 'Nur „5 N“ reicht nicht: Es kommt auch darauf an, wohin und wo die Kraft wirkt.', src: 'OPAL Ph7 2'},
    {t: '2 Kraftpfeil und Kräfte addieren', d: 1, q: 'Was gibt die Länge eines Kraftpfeils an?', a: ['Den Betrag der Kraft', 'Die Richtung der Kraft', 'Den Angriffspunkt', 'Die Masse des Körpers'], e: 'Je länger der Pfeil, desto größer die Kraft – nach dem angegebenen Maßstab.', src: 'OPAL Ph7 2'},
    {t: '2 Kraftpfeil und Kräfte addieren', d: 1, q: 'Wo beginnt ein Kraftpfeil?', a: ['Am Angriffspunkt am Körper', 'Irgendwo neben dem Körper', 'Immer am Rand des Blattes', 'An der Spitze der Kraft'], e: 'Der Anfang des Pfeils ist der Angriffspunkt – dort, wo die Kraft am Körper ansetzt.', src: 'OPAL Ph7 2 Falle'},
    {t: '2 Kraftpfeil und Kräfte addieren', d: 1, q: 'Was zeigt die Spitze eines Kraftpfeils an?', a: ['Die Richtung der Kraft', 'Den Betrag der Kraft', 'Den Angriffspunkt', 'Den Maßstab'], e: 'Die Spitze zeigt, wohin die Kraft wirkt.', src: 'OPAL Ph7 2'},
    {t: '2 Kraftpfeil und Kräfte addieren', d: 1, q: 'Zwei Kräfte wirken in dieselbe Richtung. Wie fasst man sie zusammen?', a: ['Man addiert die Beträge.', 'Man subtrahiert die Beträge.', 'Man multipliziert die Beträge.', 'Man nimmt nur die größere Kraft.'], e: 'Gleiche Richtung: addieren. Entgegengesetzt: die kleinere von der größeren abziehen.', src: 'OPAL Ph7 2'},
    {t: '2 Kraftpfeil und Kräfte addieren', d: 1, q: 'Zwei gleich große Kräfte ziehen entgegengesetzt an einem Körper. Was gilt?', a: ['Sie heben sich auf: Gleichgewicht.', 'Er bewegt sich nach links.', 'Die Kräfte addieren sich.', 'Er wird dadurch schwerer.'], e: 'Gleich groß und entgegengesetzt: Die resultierende Kraft ist 0 N.', src: 'OPAL Ph7 2'},
    {t: '2 Kraftpfeil und Kräfte addieren', d: 2, q: 'Maßstab 1 cm ≙ 10 N. Wie lang ist der Pfeil für 30 N?', a: ['3 cm', '30 cm', '0,3 cm', '300 cm'], e: 'Kraft → Länge: teilen. 30 N : 10 N = 3, also 3 cm.', src: 'OPAL Ph7 2'},
    {t: '2 Kraftpfeil und Kräfte addieren', d: 2, q: 'Maßstab 1 cm ≙ 5 N. Wie lang ist der Pfeil für 40 N?', a: ['8 cm', '4 cm', '200 cm', '45 cm'], e: '40 N : 5 N = 8, also 8 cm.', src: 'OPAL Ph7 2'},
    {t: '2 Kraftpfeil und Kräfte addieren', d: 2, q: 'Maßstab 1 cm ≙ 20 N. Ein Kraftpfeil ist 3,5 cm lang. Wie groß ist die Kraft?', a: ['70 N', '35 N', '23,5 N', '5,7 N'], e: 'Länge → Kraft: malnehmen. 3,5 · 20 N = 70 N.', src: 'OPAL Ph7 2'},
    {t: '2 Kraftpfeil und Kräfte addieren', d: 2, q: 'Zwei Hunde ziehen an ihren Leinen in dieselbe Richtung, mit 80 N und 60 N. Wie groß ist die Gesamtkraft?', a: ['140 N', '20 N', '80 N', '4800 N'], e: 'Gleiche Richtung, also addieren: 80 N + 60 N = 140 N.', src: 'OPAL Ph7 2'},
    {t: '2 Kraftpfeil und Kräfte addieren', d: 2, q: 'Tauziehen: Team A zieht mit 300 N nach links, Team B mit 350 N nach rechts. Wie groß ist die resultierende Kraft?', a: ['50 N nach rechts', '50 N nach links', '650 N nach rechts', '0 N'], e: 'Entgegengesetzt: 350 N − 300 N = 50 N. Sie zeigt zur größeren Kraft, also nach rechts.', src: 'OPAL Ph7 2'},
    {t: '2 Kraftpfeil und Kräfte addieren', d: 3, q: 'Auf eine Kiste wirken 50 N und 20 N nach rechts sowie 30 N nach links. Wie groß ist die resultierende Kraft?', a: ['40 N nach rechts', '100 N nach rechts', '0 N', '60 N nach links'], e: 'Nach rechts: 50 N + 20 N = 70 N. Dann 70 N − 30 N = 40 N nach rechts.', src: 'OPAL Ph7 2'},
    {t: '2 Kraftpfeil und Kräfte addieren', d: 3, q: 'An einem Seil ziehen links und rechts je 200 N. Welche Aussage stimmt?', a: ['Die resultierende Kraft ist 0 N, das Seil wird trotzdem gespannt.', 'Die resultierende Kraft ist 400 N, das Seil reißt sofort.', 'Auf das Seil wirkt überhaupt keine Kraft, es bleibt locker.', 'Das Seil bewegt sich mit 200 N nach rechts weg.'], e: 'Gleichgewicht heißt nicht „es passiert nichts“: Die Bewegung ändert sich nicht, aber die Form schon.', src: 'OPAL Ph7 2 Falle'},

    // ---------- 3 Gewichtskraft und Ortsfaktor ----------
    {t: '3 Gewichtskraft und Ortsfaktor', d: 1, q: 'Was gibt die Masse eines Körpers an?', a: ['Wie viel Stoff in ihm steckt', 'Wie stark die Erde an ihm zieht', 'Wie viel Platz er einnimmt', 'Wie schnell er nach unten fällt'], e: 'Die Masse $m$ wird in kg angegeben und ist überall gleich – auch auf dem Mond.', src: 'OPAL Ph7 3 Steckbrief'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 1, q: 'Was ist die Gewichtskraft?', a: ['Die Kraft, mit der ein Himmelskörper an einem Körper zieht', 'Die Menge Stoff, die in einem Körper steckt', 'Die Kraft, mit der eine Feder zurückzieht', 'Die Kraft, mit der ein Magnet Eisen anzieht'], e: 'Die Gewichtskraft $F_G$ ist eine Kraft, also in Newton – und sie hängt vom Ort ab.', src: 'OPAL Ph7 3 Steckbrief'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 1, q: 'In welcher Einheit gibt man die Gewichtskraft an?', a: ['Newton (N)', 'Kilogramm (kg)', 'Gramm (g)', 'Newton je Kilogramm (N/kg)'], e: 'Die Gewichtskraft ist eine Kraft – also Newton. N/kg ist die Einheit des Ortsfaktors.', src: 'OPAL Ph7 3'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 1, q: 'Mit welchem Ortsfaktor rechnen wir auf der Erde?', a: ['$g$ = 10 N/kg', '$g$ = 1,6 N/kg', '$g$ = 100 N/kg', '$g$ = 1 N/kg'], e: 'Im Tabellenwerk steht 9,81 N/kg – wir rechnen gerundet mit 10 N/kg. 1,6 N/kg gilt auf dem Mond.', src: 'OPAL Ph7 3'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 1, q: 'Wie lautet die Gleichung für die Gewichtskraft?', a: ['$F_G = m · g$', '$F_G = {{m|g}}$', '$F_G = m + g$', '$m = F_G · g$'], e: 'Gewichtskraft = Masse · Ortsfaktor.', src: 'OPAL Ph7 3'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 1, q: 'Ein Astronaut fliegt von der Erde zum Mond. Was ändert sich?', a: ['Nur die Gewichtskraft', 'Nur die Masse', 'Masse und Gewichtskraft', 'Gar nichts'], e: 'Die Masse bleibt gleich. Der Mond zieht schwächer, also ist die Gewichtskraft kleiner.', src: 'OPAL Ph7 3'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 1, q: 'Wovon hängt der Ortsfaktor $g$ ab?', a: ['Vom Himmelskörper, auf dem man ist', 'Von der Masse des Körpers', 'Von der Form des Körpers', 'Vom Stoff, aus dem der Körper ist'], e: 'Auf der Erde 10 N/kg, auf dem Mond 1,6 N/kg – egal, welcher Körper.', src: 'OPAL Ph7 3'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 1, q: 'Rechne um: 350 g = ?', a: ['0,35 kg', '3,5 kg', '35 kg', '0,035 kg'], e: '1 kg = 1000 g, also 350 g : 1000 = 0,35 kg. Vor dem Rechnen muss die Masse in kg stehen.', src: 'OPAL Ph7 3 Steckbrief'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 2, q: 'Eine Packung Mehl hat eine Masse von 2 kg. Wie groß ist ihre Gewichtskraft auf der Erde?', a: ['20 N', '2 N', '0,2 N', '12 N'], e: '$F_G = m · g$ = 2 kg · 10 N/kg = 20 N.', src: 'OPAL Ph7 3'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 2, q: 'Ein Apfel hat eine Masse von 350 g. Wie groß ist seine Gewichtskraft?', a: ['3,5 N', '3500 N', '35 N', '0,35 N'], e: 'Erst umrechnen: 350 g = 0,35 kg. $F_G$ = 0,35 kg · 10 N/kg = 3,5 N.', src: 'OPAL Ph7 3'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 2, q: 'Ein Auto hat eine Masse von 1,2 t. Wie groß ist seine Gewichtskraft?', a: ['12 000 N', '1200 N', '12 N', '120 000 N'], e: '1,2 t = 1200 kg. $F_G$ = 1200 kg · 10 N/kg = 12 000 N = 12 kN.', src: 'OPAL Ph7 3'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 2, q: 'Ein Hund hat eine Gewichtskraft von 150 N. Welche Masse hat er?', a: ['15 kg', '1500 kg', '150 kg', '1,5 kg'], e: '$m = {{F_G|g}}$ = {{150 N|10 N/kg}} = 15 kg.', src: 'OPAL Ph7 3'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 2, q: 'Mit welcher Gleichung berechnet man die Masse, wenn die Gewichtskraft bekannt ist?', a: ['$m = {{F_G|g}}$', '$m = F_G · g$', '$m = {{g|F_G}}$', '$m = F_G − g$'], e: 'Im Formeldreieck $m$ zudecken: $F_G$ steht über $g$ – also teilen.', src: 'OPAL Ph7 3 Formeldreieck'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 2, q: 'Ein Astronaut hat eine Masse von 80 kg. Wie groß ist seine Gewichtskraft auf dem Mond ($g$ = 1,6 N/kg)?', a: ['128 N', '800 N', '80 N', '50 N'], e: '$F_G$ = 80 kg · 1,6 N/kg = 128 N. Seine Masse bleibt 80 kg.', src: 'OPAL Ph7 3'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 2, q: 'Welche Masse hat ein Körper auf dem Mond, der auf der Erde 60 kg hat?', a: ['60 kg', '96 kg', '600 kg', '10 kg'], e: 'Die Masse ist überall gleich. Nur die Gewichtskraft ändert sich.', src: 'OPAL Ph7 3 Falle'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 3, q: 'Ein Kraftmesser zeigt 2,5 N an. Welche Masse hat der Körper, der daran hängt?', a: ['250 g', '25 kg', '2,5 kg', '25 g'], e: '$m = {{F_G|g}}$ = {{2,5 N|10 N/kg}} = 0,25 kg = 250 g.', src: 'OPAL Ph7 3'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 3, q: 'Eine Küchenwaage zeigt auf der Erde 1 kg Zucker an. Was würde sie auf dem Mond anzeigen?', a: ['Etwa 160 g, obwohl die Masse 1 kg bleibt', 'Genau 1 kg, weil die Masse gleich bleibt', 'Etwa 6 kg, weil der Mond kleiner ist', 'Gar nichts, weil auf dem Mond nichts zieht'], e: 'Die Waage misst die Gewichtskraft: 1,6 N statt 10 N – sie rechnet das auf der Erde in 160 g um.', src: 'OPAL Ph7 3'},

    // ---------- 4 Das Hooke’sche Gesetz ----------
    {t: '4 Das Hooke’sche Gesetz', d: 1, q: 'Was ist die Verlängerung $s$ einer Feder?', a: ['Das Stück, um das sie länger wird', 'Die ganze Länge der Feder mit Last', 'Die Länge der Feder ohne Last', 'Der Durchmesser der Feder'], e: 'Man misst ab der Nullmarke – dort, wo das Federende ohne Last hängt.', src: 'OPAL Ph7 4'},
    {t: '4 Das Hooke’sche Gesetz', d: 1, q: 'Was besagt das Hooke’sche Gesetz?', a: ['Kraft und Verlängerung sind proportional.', 'Die Verlängerung ist immer gleich groß.', 'Doppelte Kraft gibt halbe Verlängerung.', 'Unter Kraft wird die Feder kürzer.'], e: 'Doppelte Kraft – doppelte Verlängerung. Das gilt, solange man die Feder nicht überdehnt.', src: 'OPAL Ph7 4'},
    {t: '4 Das Hooke’sche Gesetz', d: 1, q: 'Wie sieht das $F$-$s$-Diagramm einer Feder aus, für die das Hooke’sche Gesetz gilt?', a: ['Eine Gerade durch den Ursprung', 'Eine waagerechte Gerade', 'Eine Kurve, die immer steiler wird', 'Eine Gerade, die bei 5 N beginnt'], e: 'Proportionale Größen ergeben eine Gerade durch den Ursprung.', src: 'OPAL Ph7 4'},
    {t: '4 Das Hooke’sche Gesetz', d: 1, q: 'Was gibt die Federkonstante $D$ an?', a: ['Die Kraft für 1 cm Verlängerung', 'Die Länge der Feder ohne Last', 'Die Masse der Feder selbst', 'Die größte erlaubte Verlängerung'], e: '$D$ sagt, wie hart eine Feder ist: wie viel Newton man braucht, um sie um 1 cm zu dehnen.', src: 'OPAL Ph7 4 Steckbrief'},
    {t: '4 Das Hooke’sche Gesetz', d: 1, q: 'In welcher Einheit geben wir die Federkonstante an?', a: ['N/cm', 'cm/N', 'N · cm', 'kg/cm'], e: 'Newton je Zentimeter: Kraft geteilt durch Verlängerung.', src: 'OPAL Ph7 4 Steckbrief'},
    {t: '4 Das Hooke’sche Gesetz', d: 1, q: 'Wie berechnet man die Federkonstante?', a: ['$D = {{F|s}}$', '$D = F · s$', '$D = {{s|F}}$', '$D = F + s$'], e: 'Federkonstante = Kraft geteilt durch Verlängerung.', src: 'OPAL Ph7 4 Steckbrief'},
    {t: '4 Das Hooke’sche Gesetz', d: 1, q: 'Eine Feder ist sehr hart. Was gilt für ihre Federkonstante?', a: ['Sie ist groß.', 'Sie ist klein.', 'Sie ist null.', 'Sie ist negativ.'], e: 'Große Federkonstante: Man braucht viel Kraft für 1 cm – die Feder ist hart.', src: 'OPAL Ph7 4'},
    {t: '4 Das Hooke’sche Gesetz', d: 2, q: 'Ohne Last ist eine Feder 8 cm lang, mit Last 12 cm. Wie groß ist die Verlängerung?', a: ['4 cm', '12 cm', '20 cm', '8 cm'], e: '$s$ = 12 cm − 8 cm = 4 cm.', src: 'OPAL Ph7 4'},
    {t: '4 Das Hooke’sche Gesetz', d: 2, q: 'Eine Feder wird mit 6 N um 4 cm verlängert. Wie groß ist ihre Federkonstante?', a: ['1,5 N/cm', '24 N/cm', '0,67 N/cm', '2 N/cm'], e: '$D = {{F|s}}$ = {{6 N|4 cm}} = 1,5 N/cm.', src: 'OPAL Ph7 4'},
    {t: '4 Das Hooke’sche Gesetz', d: 2, q: 'Eine Feder mit $D$ = 3 N/cm wird mit 12 N belastet. Um wie viel wird sie länger?', a: ['4 cm', '36 cm', '0,25 cm', '15 cm'], e: '$s = {{F|D}}$ = {{12 N|3 N/cm}} = 4 cm.', src: 'OPAL Ph7 4'},
    {t: '4 Das Hooke’sche Gesetz', d: 2, q: 'Eine Feder mit $D$ = 0,8 N/cm ist um 5 cm verlängert. Wie groß ist die Kraft?', a: ['4 N', '6,25 N', '5,8 N', '0,16 N'], e: '$F = D · s$ = 0,8 N/cm · 5 cm = 4 N.', src: 'OPAL Ph7 4'},
    {t: '4 Das Hooke’sche Gesetz', d: 2, q: 'Eine Feder wird mit 2 N um 3 cm länger. Um wie viel wird sie mit 4 N länger?', a: ['6 cm', '5 cm', '1,5 cm', '12 cm'], e: 'Doppelte Kraft, doppelte Verlängerung: 2 · 3 cm = 6 cm.', src: 'OPAL Ph7 4'},
    {t: '4 Das Hooke’sche Gesetz', d: 2, q: 'Man hängt mehr Massestücke an dieselbe Feder. Was passiert mit $D$?', a: ['$D$ bleibt gleich.', '$D$ wird größer.', '$D$ wird kleiner.', '$D$ verdoppelt sich.'], e: '$D$ gehört zur Feder. Nur $F$ und $s$ werden größer.', src: 'OPAL Ph7 4 Falle'},
    {t: '4 Das Hooke’sche Gesetz', d: 2, q: 'Im $F$-$s$-Diagramm ist die Gerade von Feder A steiler als die von Feder B. Welche Feder ist härter?', a: ['Feder A', 'Feder B', 'Beide gleich', 'Nicht ablesbar'], e: 'Die steilere Gerade gehört zur härteren Feder – sie dehnt sich bei gleicher Kraft weniger.', src: 'OPAL Ph7 4 Falle'},
    {t: '4 Das Hooke’sche Gesetz', d: 3, q: 'Ohne Last ist eine Feder 8 cm lang, bei 2 N ist sie 12 cm lang. Wie lang ist sie bei 4 N?', a: ['16 cm', '24 cm', '20 cm', '8 cm'], e: 'Verlängerung bei 2 N: 4 cm. Bei 4 N doppelt: 8 cm. Länge: 8 cm + 8 cm = 16 cm.', src: 'OPAL Ph7 4 Länge-Falle'},
    {t: '4 Das Hooke’sche Gesetz', d: 3, q: 'Messreihe an einer Feder: 1 N → 2,5 cm, 2 N → 5 cm, 3 N → 7,5 cm. Was folgt daraus?', a: ['Proportional, $D$ = 0,4 N/cm', 'Proportional, $D$ = 2,5 N/cm', 'Nicht proportional', 'Proportional, $D$ = 7,5 N/cm'], e: 'Quotientenvergleich: {{1 N|2,5 cm}} = {{2 N|5 cm}} = {{3 N|7,5 cm}} = 0,4 N/cm – überall gleich.', src: 'OPAL Ph7 4'},

    // ---------- 5 Hebel und Hebelgesetz ----------
    {t: '5 Hebel und Hebelgesetz', d: 1, q: 'Was ist ein Hebel?', a: ['Ein fester Körper, der sich um einen Drehpunkt dreht', 'Eine Feder, die sich unter einer Kraft dehnen lässt', 'Ein Seil, das über eine feste Rolle läuft', 'Ein Magnet mit einem Nord- und einem Südpol'], e: 'Beispiele: Wippe, Schere, Zange, Brechstange, Schraubenschlüssel.', src: 'OPAL Ph7 5'},
    {t: '5 Hebel und Hebelgesetz', d: 1, q: 'Wie heißt der Abstand vom Drehpunkt bis zur Stelle, an der eine Kraft angreift?', a: ['Arm', 'Achse', 'Verlängerung', 'Pfeil'], e: 'Kraftarm $l_1$ und Lastarm $l_2$ – immer vom Drehpunkt aus gemessen.', src: 'OPAL Ph7 5'},
    {t: '5 Hebel und Hebelgesetz', d: 1, q: 'Wie lautet das Hebelgesetz?', a: ['$F_1 · l_1 = F_2 · l_2$', '$F_1 + l_1 = F_2 + l_2$', '$F_1 · F_2 = l_1 · l_2$', '$F_1 · l_2 = F_2 · l_1$'], e: 'Gleichgewicht, wenn Kraft mal Arm auf beiden Seiten gleich ist.', src: 'OPAL Ph7 5'},
    {t: '5 Hebel und Hebelgesetz', d: 1, q: 'Der Arm wird doppelt so lang. Welche Kraft braucht man dann?', a: ['Die halbe Kraft', 'Die doppelte Kraft', 'Dieselbe Kraft', 'Ein Viertel der Kraft'], e: 'Je länger der Arm, desto kleiner die Kraft: doppelter Arm – halbe Kraft.', src: 'OPAL Ph7 5 Falle'},
    {t: '5 Hebel und Hebelgesetz', d: 1, q: 'Welcher Gegenstand ist ein Hebel?', a: ['Schraubenschlüssel', 'Gummiband', 'Kompass', 'Luftballon'], e: 'Er dreht sich um die Schraube als Drehpunkt.', src: 'OPAL Ph7 5'},
    {t: '5 Hebel und Hebelgesetz', d: 1, q: 'Von wo aus misst man die Arme eines Hebels?', a: ['Vom Drehpunkt aus', 'Vom Ende des Hebels', 'Von der Mitte des Hebels', 'Vom Boden aus'], e: 'Ein Arm ist der Abstand vom Drehpunkt bis zum Angriffspunkt der Kraft.', src: 'OPAL Ph7 5 Falle'},
    {t: '5 Hebel und Hebelgesetz', d: 2, q: 'Links wirken 20 N im Abstand 30 cm vom Drehpunkt. Rechts greift eine Kraft im Abstand 60 cm an. Wie groß muss sie sein?', a: ['10 N', '40 N', '20 N', '90 N'], e: '20 N · 30 cm = 600 N·cm. Welche Zahl mal 60 ergibt 600? 10, also 10 N.', src: 'OPAL Ph7 5'},
    {t: '5 Hebel und Hebelgesetz', d: 2, q: 'Links wirken 15 N im Abstand 20 cm. Rechts hängt ein Körper mit 5 N. Wie weit vom Drehpunkt muss er hängen?', a: ['60 cm', '4 cm', '100 cm', '20 cm'], e: '15 N · 20 cm = 300 N·cm. Welche Zahl mal 5 ergibt 300? 60, also 60 cm.', src: 'OPAL Ph7 5'},
    {t: '5 Hebel und Hebelgesetz', d: 2, q: 'Max (400 N) sitzt 1,5 m vom Drehpunkt einer Wippe entfernt, Lena auf der anderen Seite 2 m. Die Wippe ist im Gleichgewicht. Welche Gewichtskraft hat Lena?', a: ['300 N', '533 N', '400 N', '600 N'], e: '400 N · 1,5 m = 600 N·m. Welche Zahl mal 2 ergibt 600? 300 – Lena sitzt weiter außen, braucht also weniger.', src: 'OPAL Ph7 5'},
    {t: '5 Hebel und Hebelgesetz', d: 2, q: 'Ein Vater (800 N) sitzt 1 m vom Drehpunkt einer Wippe entfernt. Wo muss seine Tochter (400 N) sitzen?', a: ['2 m vom Drehpunkt', '0,5 m vom Drehpunkt', '1 m vom Drehpunkt', '4 m vom Drehpunkt'], e: '800 N · 1 m = 800 N·m. Welche Zahl mal 400 ergibt 800? 2, also 2 m.', src: 'OPAL Ph7 5'},
    {t: '5 Hebel und Hebelgesetz', d: 2, q: 'Links ist ein Arm 0,5 m lang, rechts 30 cm. Was musst du vor dem Rechnen tun?', a: ['Beide Arme in dieselbe Einheit umrechnen', 'Beide Arme zusammenzählen', 'Den kürzeren Arm verdoppeln', 'Nichts, man kann gleich rechnen'], e: 'Beide Arme brauchen dieselbe Einheit: 0,5 m = 50 cm.', src: 'OPAL Ph7 5'},
    {t: '5 Hebel und Hebelgesetz', d: 3, q: 'Ein Massestück von 500 g hängt 20 cm links vom Drehpunkt. Rechts zieht ein Kraftmesser 10 cm vom Drehpunkt nach unten. Was zeigt er im Gleichgewicht?', a: ['10 N', '2,5 N', '5 N', '1000 N'], e: 'Erst die Kraft: 500 g → 5 N. Dann 5 N · 20 cm = 100 N·cm. Welche Zahl mal 10 ergibt 100? 10 N.', src: 'OPAL Ph7 5 Falle'},
    {t: '5 Hebel und Hebelgesetz', d: 3, q: 'Warum lässt sich eine feste Schraube mit einem langen Schraubenschlüssel leichter lösen?', a: ['Längerer Arm, also reicht eine kleinere Kraft', 'Der lange Schlüssel ist schwerer und hilft mit', 'Am langen Schlüssel ist die Reibung kleiner', 'Der lange Schlüssel dreht die Schraube schneller'], e: 'Kraft mal Arm muss gleich groß bleiben. Je länger der Arm, desto kleiner die nötige Kraft.', src: 'OPAL Ph7 5'},

    // ---------- 6 Reibungskräfte ----------
    {t: '6 Reibungskräfte', d: 1, q: 'In welche Richtung wirkt die Reibungskraft?', a: ['Der Bewegung entgegen', 'In Richtung der Bewegung', 'Immer senkrecht nach oben', 'Immer zum Erdmittelpunkt'], e: 'Reibung bremst: Sie wirkt gegen die Bewegung.', src: 'OPAL Ph7 6'},
    {t: '6 Reibungskräfte', d: 1, q: 'Was ist beim selben Körper größer?', a: ['Die Haftreibungskraft', 'Die Gleitreibungskraft', 'Beide sind immer gleich', 'Das ist jedes Mal anders'], e: 'Deshalb ist Anschieben schwerer als Weiterschieben.', src: 'OPAL Ph7 6'},
    {t: '6 Reibungskräfte', d: 1, q: 'Ein schwerer Schrank lässt sich nicht verschieben. Welche Reibung hält ihn fest?', a: ['Haftreibung', 'Gleitreibung', 'Luftwiderstand', 'Magnetkraft'], e: 'Der Schrank ruht noch – die Haftreibung verhindert, dass er losrutscht.', src: 'OPAL Ph7 6'},
    {t: '6 Reibungskräfte', d: 1, q: 'Ein Schlitten saust den Hang hinunter. Welche Reibung wirkt zwischen Kufen und Schnee?', a: ['Gleitreibung', 'Haftreibung', 'Gar keine', 'Magnetkraft'], e: 'Die Kufen gleiten über den Schnee.', src: 'OPAL Ph7 6'},
    {t: '6 Reibungskräfte', d: 1, q: 'Ein Radiergummi wird über das Papier gerieben. Welche Reibung wirkt?', a: ['Gleitreibung', 'Haftreibung', 'Gar keine', 'Luftwiderstand'], e: 'Der Radiergummi gleitet über das Papier.', src: 'OPAL Ph7 6'},
    {t: '6 Reibungskräfte', d: 1, q: 'Wovon hängt die Reibungskraft ab?', a: ['Von Gewichtskraft und Oberflächen', 'Von der Größe der Auflagefläche', 'Von der Farbe der beiden Körper', 'Von der Temperatur im Raum'], e: 'Je schwerer der Körper und je rauer die Flächen, desto größer die Reibungskraft.', src: 'OPAL Ph7 6'},
    {t: '6 Reibungskräfte', d: 1, q: 'Wo ist Reibung erwünscht?', a: ['Bei Bremsen und Schuhsohlen', 'Im Lager eines Fahrrads', 'Zwischen Zahnrädern im Motor', 'An Skiern auf der Piste'], e: 'Ohne Reibung könnte man weder bremsen noch sicher laufen.', src: 'OPAL Ph7 6'},
    {t: '6 Reibungskräfte', d: 1, q: 'Wie kann man die Reibung verkleinern?', a: ['Öl oder Fett dazwischen geben', 'Sand auf die Fläche streuen', 'Schuhe mit tiefem Profil tragen', 'Den Körper schwerer machen'], e: 'Öl und Fett verringern Reibung und Verschleiß an Maschinen.', src: 'OPAL Ph7 6'},
    {t: '6 Reibungskräfte', d: 1, q: 'Was ist der Luftwiderstand?', a: ['Eine bremsende Kraft beim Bewegen durch Luft', 'Die Gewichtskraft der Luft über uns', 'Eine magnetische Kraft in der Luft', 'Die Kraft, mit der Luft nach oben drückt'], e: 'Er wirkt wie eine Reibung der Bewegung entgegen – beim Radfahren spürt man ihn deutlich.', src: 'Lehrplan Ph7 LB1'},
    {t: '6 Reibungskräfte', d: 2, q: 'Ein Klotz wird am Kraftmesser gezogen. Bis zum Losrutschen steigt die Anzeige auf 4 N, beim gleichmäßigen Ziehen zeigt sie 2,5 N. Wie groß ist die Haftreibungskraft?', a: ['4 N', '2,5 N', '6,5 N', '1,5 N'], e: 'Die Haftreibung liest man im Moment des Losrutschens ab: 4 N. Gleitreibung: 2,5 N.', src: 'OPAL Ph7 6'},
    {t: '6 Reibungskräfte', d: 2, q: 'Wie misst man die Gleitreibungskraft?', a: ['Beim gleichmäßigen Ziehen ablesen', 'Im Moment des Losrutschens ablesen', 'Den Körper auf eine Waage stellen', 'Mit einem Lineal den Weg messen'], e: 'Für die Reibungskraft gibt es in Klasse 7 keine Gleichung – sie wird gemessen.', src: 'OPAL Ph7 6 Falle'},
    {t: '6 Reibungskräfte', d: 3, q: 'Ein Klotz wird einmal flach und einmal hochkant über den Tisch gezogen. Was zeigt der Kraftmesser?', a: ['Fast dasselbe', 'Hochkant viel mehr', 'Flach viel mehr', 'Flach doppelt so viel'], e: 'Gewichtskraft und Oberflächen bleiben gleich. Die Größe der Auflagefläche spielt kaum eine Rolle.', src: 'OPAL Ph7 6 Falle'},
    {t: '6 Reibungskräfte', d: 3, q: 'Auf einen schweren Holzklotz wird ein zweiter gleicher Klotz gelegt. Was passiert mit der Reibungskraft beim Ziehen?', a: ['Sie wird größer.', 'Sie wird kleiner.', 'Sie bleibt gleich.', 'Sie wird null.'], e: 'Die Reibungskraft hängt von der Gewichtskraft ab – und die ist jetzt größer.', src: 'OPAL Ph7 6'},

    // ---------- 7 Magnete und das magnetische Feld ----------
    {t: '7 Magnete und magnetisches Feld', d: 1, q: 'Welche Stoffe zieht ein Magnet an?', a: ['Eisen, Nickel und Cobalt', 'Alle Metalle', 'Kupfer, Aluminium, Eisen', 'Holz, Glas und Kunststoff'], e: '„Metall“ heißt nicht automatisch „magnetisch“: Kupfer und Aluminium werden nicht angezogen.', src: 'OPAL Ph7 7'},
    {t: '7 Magnete und magnetisches Feld', d: 1, q: 'Was passiert, wenn man zwei Nordpole einander nähert?', a: ['Sie stoßen sich ab.', 'Sie ziehen sich an.', 'Es passiert nichts.', 'Sie werden zu Südpolen.'], e: 'Gleichnamige Pole stoßen sich ab.', src: 'OPAL Ph7 7'},
    {t: '7 Magnete und magnetisches Feld', d: 1, q: 'Was gilt für einen Nordpol und einen Südpol?', a: ['Sie ziehen sich an.', 'Sie stoßen sich ab.', 'Sie wirken nicht aufeinander.', 'Sie heben sich auf.'], e: 'Ungleichnamige Pole ziehen sich an.', src: 'OPAL Ph7 7'},
    {t: '7 Magnete und magnetisches Feld', d: 1, q: 'Welche Farbe hat bei unseren Magneten der Nordpol?', a: ['Rot', 'Grün', 'Blau', 'Gelb'], e: 'Nordpol rot, Südpol grün.', src: 'OPAL Ph7 7'},
    {t: '7 Magnete und magnetisches Feld', d: 1, q: 'Braucht die magnetische Kraft eine Berührung?', a: ['Nein, sie wirkt ohne Berührung.', 'Ja, nur bei Berührung.', 'Nur in einem luftleeren Raum.', 'Nur, wenn Strom fließt.'], e: 'Ein Magnet zieht eine Büroklammer auch durch die Luft an.', src: 'OPAL Ph7 7'},
    {t: '7 Magnete und magnetisches Feld', d: 1, q: 'Wie verlaufen magnetische Feldlinien außerhalb eines Magneten?', a: ['Vom Nordpol zum Südpol', 'Vom Südpol zum Nordpol', 'Im Kreis um den Nordpol', 'Gerade vom Magneten weg'], e: 'Sie kommen aus dem Nordpol heraus und gehen in den Südpol hinein.', src: 'OPAL Ph7 7'},
    {t: '7 Magnete und magnetisches Feld', d: 1, q: 'Wo ist das Feld eines Stabmagneten am stärksten?', a: ['An den Polen', 'In der Mitte', 'Weit weg vom Magneten', 'Überall gleich'], e: 'Dort liegen die Feldlinien am dichtesten.', src: 'OPAL Ph7 7'},
    {t: '7 Magnete und magnetisches Feld', d: 1, q: 'Können sich magnetische Feldlinien schneiden?', a: ['Nein, nie', 'Ja, an den Polen', 'Ja, in der Mitte', 'Nur bei starken Magneten'], e: 'Feldlinien schneiden sich nie.', src: 'OPAL Ph7 7'},
    {t: '7 Magnete und magnetisches Feld', d: 1, q: 'Wozu streut man Eisenfeilspäne um einen Magneten?', a: ['Um das Feldlinienbild sichtbar zu machen', 'Um den Magneten stärker zu machen', 'Um den Magneten unmagnetisch zu machen', 'Um die Kraft in Newton zu messen'], e: 'Feldlinien sind ein Modell. Die Späne machen das Muster sichtbar.', src: 'OPAL Ph7 7'},
    {t: '7 Magnete und magnetisches Feld', d: 2, q: 'Was überträgt die magnetische Kraft ohne Berührung?', a: ['Das magnetische Feld', 'Die Luft um den Magneten', 'Echte Fäden aus Feldlinien', 'Die elektrische Ladung'], e: 'Um jeden Magneten gibt es ein magnetisches Feld, das die Kraft überträgt.', src: 'OPAL Ph7 7'},
    {t: '7 Magnete und magnetisches Feld', d: 2, q: 'Ein Stabmagnet zerbricht in der Mitte. Was hast du dann?', a: ['Zwei Magnete mit je Nord- und Südpol', 'Einen einzelnen Nordpol und Südpol', 'Zwei Stücke, die nicht mehr magnetisch sind', 'Zwei Stücke, die beide nur Nordpole sind'], e: 'Einen einzelnen Pol allein gibt es nicht.', src: 'OPAL Ph7 7 Falle'},
    {t: '7 Magnete und magnetisches Feld', d: 2, q: 'Warum zeigt eine Kompassnadel nach Norden?', a: ['Sie richtet sich im Magnetfeld der Erde aus.', 'Sie wird vom Polarstern angezogen.', 'Sie besteht aus Kupfer und dreht sich so.', 'Der Wind dreht sie immer nach Norden.'], e: 'Die Nadel ist ein kleiner Magnet. Die Erde hat ein magnetisches Feld.', src: 'OPAL Ph7 7'},
    {t: '7 Magnete und magnetisches Feld', d: 2, q: 'Du hältst den Nordpol eines Magneten an ein Ende eines unbeschrifteten Magneten. Sie stoßen sich ab. Welcher Pol ist das?', a: ['Ein Nordpol', 'Ein Südpol', 'Das kann man nicht sagen', 'Gar kein Pol'], e: 'Abstoßen tun sich nur gleichnamige Pole.', src: 'OPAL Ph7 7'},
    {t: '7 Magnete und magnetisches Feld', d: 3, q: 'Ein Ende eines unbeschrifteten Magneten zieht einen Eisennagel an. Was weißt du über dieses Ende?', a: ['Nichts über den Pol – Eisen wird von beiden Polen angezogen', 'Es ist ein Nordpol, denn Nordpole ziehen Eisen an', 'Es ist ein Südpol, denn Südpole ziehen Eisen an', 'Es ist gar kein Pol, sondern die Mitte des Magneten'], e: 'Anziehen allein beweist nichts. Nur das Abstoßen verrät den Pol.', src: 'OPAL Ph7 7'},

    // ---------- 8 Elektromagnete ----------
    {t: '8 Elektromagnete', d: 1, q: 'Woraus besteht ein Elektromagnet?', a: ['Spule mit Eisenkern', 'Stabmagnet mit Draht', 'Zwei Dauermagneten', 'Batterie mit Lampe'], e: 'Eine Spule aus Draht, in der ein Eisenkern steckt – dazu eine Stromquelle.', src: 'OPAL Ph7 8'},
    {t: '8 Elektromagnete', d: 1, q: 'Wann ist ein Elektromagnet magnetisch?', a: ['Wenn Strom durch die Spule fließt', 'Immer, auch ganz ohne Strom', 'Nur, wenn er sehr warm ist', 'Nur in der Nähe von Eisen'], e: 'Strom an: magnetisch. Strom aus: (fast) nicht magnetisch.', src: 'OPAL Ph7 8'},
    {t: '8 Elektromagnete', d: 1, q: 'Wie macht man einen Elektromagneten stärker?', a: ['Mehr Windungen', 'Weniger Windungen', 'Eisenkern herausnehmen', 'Weniger Strom'], e: 'Stärker wird er durch mehr Windungen, größere Stromstärke und einen Eisenkern.', src: 'OPAL Ph7 8'},
    {t: '8 Elektromagnete', d: 1, q: 'Was bewirkt der Eisenkern in einer Spule?', a: ['Er verstärkt die magnetische Wirkung.', 'Er schwächt die magnetische Wirkung.', 'Er ersetzt die Stromquelle.', 'Er macht die Spule zum Dauermagneten.'], e: 'Ohne Strom wirkt der Kern kaum – mit Strom verstärkt er die Spule sehr deutlich.', src: 'OPAL Ph7 8'},
    {t: '8 Elektromagnete', d: 2, q: 'Warum hat ein Kran auf dem Schrottplatz einen Elektromagneten?', a: ['Man kann ihn abschalten, um die Last abzulegen.', 'Er ist immer stärker als jeder Dauermagnet.', 'Er zieht auch Autoteile aus Aluminium an.', 'Er kommt ganz ohne elektrischen Strom aus.'], e: 'Strom an: Das Auto hängt. Strom aus: Es fällt ab. Ein Dauermagnet ließe sich nicht abschalten.', src: 'OPAL Ph7 8'},
    {t: '8 Elektromagnete', d: 2, q: 'Welches Gerät funktioniert mit einem Elektromagneten?', a: ['Elektrische Klingel', 'Kühlschrankmagnet', 'Kompass', 'Federkraftmesser'], e: 'Auch Türöffner, Relais und Lasthebemagnet nutzen Elektromagnete.', src: 'OPAL Ph7 8'},
    {t: '8 Elektromagnete', d: 2, q: 'Was passt besser für den Verschluss einer Federmappe?', a: ['Dauermagnet', 'Elektromagnet', 'Spule ohne Kern', 'Kompassnadel'], e: 'Er soll immer halten – ganz ohne Batterie.', src: 'OPAL Ph7 8'},
    {t: '8 Elektromagnete', d: 3, q: 'Spule 1: 200 Windungen mit Eisenkern. Spule 2: 400 Windungen mit Eisenkern. Spule 3: 400 Windungen ohne Kern. Gleicher Strom. Welche Reihenfolge stimmt (stärkste zuerst)?', a: ['2, 1, 3', '3, 2, 1', '1, 2, 3', '2, 3, 1'], e: '2 > 1 (mehr Windungen), 2 > 3 (Kern fehlt), 1 > 3 (der Kern verstärkt sehr stark).', src: 'OPAL Ph7 8'},

    // ---------- 9 Elektrische Ladung und elektrisches Feld ----------
    {t: '9 Elektrische Ladung und Feld', d: 1, q: 'Wie kann man Körper elektrisch laden?', a: ['Durch Reiben', 'Durch Erwärmen', 'Durch Magnetisieren', 'Durch Wiegen'], e: 'Reibt man einen Luftballon am Pullover, werden beide geladen.', src: 'OPAL Ph7 9'},
    {t: '9 Elektrische Ladung und Feld', d: 1, q: 'Welche Arten von elektrischer Ladung gibt es?', a: ['Positive und negative', 'Nord und Süd', 'Große und kleine', 'Nur negative'], e: 'Positiv (+) und negativ (−). Nord und Süd sind Magnetpole.', src: 'OPAL Ph7 9'},
    {t: '9 Elektrische Ladung und Feld', d: 1, q: 'Was passiert mit zwei gleichnamig geladenen Körpern?', a: ['Sie stoßen sich ab.', 'Sie ziehen sich an.', 'Sie bleiben unbeeinflusst.', 'Sie werden neutral.'], e: 'Gleichnamig: abstoßen. Ungleichnamig: anziehen – wie bei Magnetpolen.', src: 'OPAL Ph7 9'},
    {t: '9 Elektrische Ladung und Feld', d: 1, q: 'Womit prüft man, ob ein Körper elektrisch geladen ist?', a: ['Elektroskop', 'Kraftmesser', 'Kompass', 'Thermometer'], e: 'Ist der Körper geladen, schlägt der Zeiger des Elektroskops aus.', src: 'OPAL Ph7 9'},
    {t: '9 Elektrische Ladung und Feld', d: 1, q: 'Wie ist der Kern eines Atoms geladen?', a: ['Positiv', 'Negativ', 'Neutral', 'Mal so, mal so'], e: 'Der Kern ist positiv, die Elektronen in der Hülle sind negativ.', src: 'OPAL Ph7 9'},
    {t: '9 Elektrische Ladung und Feld', d: 1, q: 'Welche Teilchen wandern beim Reiben von einem Körper zum anderen?', a: ['Elektronen', 'Atomkerne', 'Ganze Atome', 'Magnetpole'], e: 'Nur die Elektronen (−) wandern. Die Kerne bleiben, wo sie sind.', src: 'OPAL Ph7 9 Falle'},
    {t: '9 Elektrische Ladung und Feld', d: 1, q: 'Wie verlaufen die Feldlinien eines elektrischen Feldes?', a: ['Von + nach −', 'Von − nach +', 'Vom Nordpol zum Südpol', 'Im Kreis um die Ladung'], e: 'Elektrische Feldlinien: von + nach −. Magnetische: von N nach S.', src: 'OPAL Ph7 9'},
    {t: '9 Elektrische Ladung und Feld', d: 1, q: 'Ein Atom hat gleich viele positive und negative Ladungen. Wie ist es nach außen geladen?', a: ['Neutral', 'Positiv', 'Negativ', 'Doppelt geladen'], e: 'Gleich viele + und −: Die Ladungen gleichen sich aus.', src: 'OPAL Ph7 9'},
    {t: '9 Elektrische Ladung und Feld', d: 2, q: 'Ein Luftballon wird am Wollpullover gerieben und ist danach negativ geladen. Was ist passiert?', a: ['Elektronen wanderten vom Pullover auf den Ballon.', 'Elektronen wanderten vom Ballon auf den Pullover.', 'Positive Ladung wanderte vom Ballon zum Pullover.', 'Der Ballon hat beim Reiben neue Ladung erzeugt.'], e: 'Wer Elektronen aufnimmt, wird negativ. Der Pullover hat sie abgegeben und ist positiv.', src: 'OPAL Ph7 9'},
    {t: '9 Elektrische Ladung und Feld', d: 2, q: 'Ein Kunststoffstab wird mit einem Tuch gerieben und ist danach negativ. Wie ist das Tuch geladen?', a: ['Positiv', 'Negativ', 'Neutral', 'Magnetisch'], e: 'Das Tuch hat Elektronen an den Stab abgegeben – ihm fehlen jetzt Elektronen.', src: 'OPAL Ph7 9'},
    {t: '9 Elektrische Ladung und Feld', d: 2, q: 'Ein Atom mit 6 positiven Ladungen im Kern und 6 Elektronen gibt ein Elektron ab. Wie ist es jetzt geladen?', a: ['Positiv', 'Negativ', 'Neutral', 'Doppelt negativ'], e: '6 + und nur noch 5 −: Es fehlt ein Elektron, also positiv.', src: 'OPAL Ph7 9'},
    {t: '9 Elektrische Ladung und Feld', d: 2, q: 'Zwei Luftballons werden am selben Pullover gerieben und an Fäden nebeneinander gehängt. Was passiert?', a: ['Sie stoßen sich ab.', 'Sie ziehen sich an.', 'Es passiert nichts.', 'Sie werden neutral.'], e: 'Beide sind negativ geladen – gleichnamige Ladungen stoßen sich ab.', src: 'OPAL Ph7 9'},
    {t: '9 Elektrische Ladung und Feld', d: 3, q: 'Was haben das magnetische und das elektrische Feld gemeinsam?', a: ['Beide übertragen Kräfte ohne Berührung.', 'Beide haben einen Nord- und einen Südpol.', 'Beide wirken nur auf Eisen und Nickel.', 'Beide entstehen nur, wenn Strom fließt.'], e: 'Beide werden mit Feldlinien dargestellt; Gleichnamiges stößt sich ab, Ungleichnamiges zieht sich an.', src: 'OPAL Ph7 9'},
    {t: '9 Elektrische Ladung und Feld', d: 3, q: 'Warum werden beim Reiben immer beide Körper geladen?', a: ['Elektronen gehen über – die Ladung wird nur getrennt.', 'Beim Reiben entsteht auf beiden Körpern neue Ladung.', 'Die Wärme beim Reiben lädt beide Körper gleich auf.', 'Die Atomkerne wandern zwischen den beiden Körpern.'], e: 'Der eine bekommt Elektronen und wird negativ, dem anderen fehlen genau diese – er wird positiv.', src: 'OPAL Ph7 9'},
    {t: '9 Elektrische Ladung und Feld', d: 3, q: 'Was bedeutet „positiv geladen“?', a: ['Der Körper hat zu wenig Elektronen.', 'Der Körper hat zu viele Elektronen.', 'Der Körper hat positive Ladung bekommen.', 'Der Körper hat gar keine Elektronen.'], e: 'Beim Reiben wandern nur Elektronen. Positiv heißt: Es fehlen Elektronen.', src: 'OPAL Ph7 9 Falle'},
    // ---------- Grundlagen: Formelzeichen, Einheiten, Merksätze ----------
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Welches Formelzeichen hat die Masse?', a: ['$m$', '$M$', '$F$', 'kg'], e: 'Masse kommt von „mass“ (Menge an Stoff). kg ist die Einheit, kein Formelzeichen.', src: 'OPAL Ph7 3 Steckbrief'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'In welcher Einheit gibt man die Masse an?', a: ['Kilogramm (kg)', 'Newton (N)', 'Meter (m)', 'Sekunde (s)'], e: 'Die Einheit der Masse ist das Kilogramm, Zeichen kg.', src: 'OPAL Ph7 3 Steckbrief'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Welches Gerät misst die Masse?', a: ['Balkenwaage', 'Kraftmesser', 'Thermometer', 'Messzylinder'], e: 'Die Waage vergleicht Massen. Der Kraftmesser misst Kräfte.', src: 'OPAL Ph7 3 Steckbrief'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Was ist das Zeichen der Einheit Newton?', a: ['N', 'n', 'Nt', 'Ne'], e: 'Die Einheit Newton wird mit einem großen N abgekürzt – zu Ehren von Isaac Newton.', src: 'OPAL Ph7 1 Steckbrief'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Was bedeutet das Vorsatzzeichen „k“ vor einer Einheit?', a: ['Tausend (1000)', 'Hundert (100)', 'Tausendstel', 'Eine Million'], e: '1 kN = 1000 N und 1 kg = 1000 g.', src: 'OPAL Ph7 1'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Rechne um: 3 kg = ?', a: ['3000 g', '300 g', '30 g', '0,003 g'], e: '1 kg = 1000 g, also 3 · 1000 g = 3000 g.', src: 'OPAL Ph7 3'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Rechne um: 250 g = ?', a: ['0,25 kg', '2,5 kg', '25 kg', '0,025 kg'], e: '250 g : 1000 = 0,25 kg.', src: 'OPAL Ph7 3'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Rechne um: 1,2 m = ?', a: ['120 cm', '12 cm', '1200 cm', '0,12 cm'], e: '1 m = 100 cm, also 1,2 · 100 cm = 120 cm.', src: 'OPAL Ph7 4'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Rechne um: 35 mm = ?', a: ['3,5 cm', '35 cm', '0,35 cm', '350 cm'], e: '10 mm = 1 cm, also 35 mm : 10 = 3,5 cm.', src: 'OPAL Ph7 4'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Was ist der Unterschied zwischen Masse und Kraft?', a: ['Masse: Menge an Stoff in kg – Kraft: Wirkung in N', 'Beides ist dasselbe, nur mit anderer Einheit', 'Masse wird in N gemessen, Kraft in kg', 'Masse ist eine Kraft, die nach unten zieht'], e: 'Masse ist die Menge an Stoff (Einheit kg). Eine Kraft (Einheit N) bewirkt etwas an einem Körper.', src: 'OPAL Ph7 3'},
    {t: '1 Die Kraft und ihre Wirkungen', d: 1, q: 'Womit zeichnet man eine Kraft in einer Skizze?', a: ['Mit einem Pfeil', 'Mit einem Kreis', 'Mit einer Zickzacklinie', 'Mit einem Punkt'], e: 'Der Kraftpfeil zeigt Angriffspunkt, Richtung und Größe der Kraft.', src: 'OPAL Ph7 2'},
    {t: '2 Kraftpfeil und Kräfte addieren', d: 1, q: 'Welche drei Angaben gehören zu einer Kraft?', a: ['Angriffspunkt, Richtung, Betrag', 'Masse, Farbe, Ort', 'Anfang, Ende, Name', 'Zeit, Ort, Geschwindigkeit'], e: 'Ein Kraftpfeil zeigt alle drei: Wo greift sie an? Wohin? Wie groß?', src: 'OPAL Ph7 2'},
    {t: '2 Kraftpfeil und Kräfte addieren', d: 1, q: 'Wofür steht die Länge eines Kraftpfeils?', a: ['Für die Größe der Kraft', 'Für den Ort der Kraft', 'Für die Zeit der Kraft', 'Für die Masse des Körpers'], e: 'Ein längerer Pfeil bedeutet eine größere Kraft (im selben Maßstab).', src: 'OPAL Ph7 2'},
    {t: '2 Kraftpfeil und Kräfte addieren', d: 1, q: 'Wofür steht die Pfeilspitze eines Kraftpfeils?', a: ['Für die Richtung der Kraft', 'Für die Größe der Kraft', 'Für die Masse', 'Für den Stoff'], e: 'Die Spitze zeigt, in welche Richtung die Kraft wirkt.', src: 'OPAL Ph7 2'},
    {t: '2 Kraftpfeil und Kräfte addieren', d: 1, q: 'Zwei gleich große Kräfte wirken in entgegengesetzte Richtung auf denselben Körper. Wie groß ist die Gesamtkraft?', a: ['0 N', 'Doppelt so groß wie eine Kraft', 'Genauso groß wie eine Kraft', 'Nicht bestimmbar'], e: 'Gleich große, entgegengesetzte Kräfte heben sich auf: Gleichgewicht.', src: 'OPAL Ph7 2'},
    {t: '2 Kraftpfeil und Kräfte addieren', d: 1, q: 'Zwei Kräfte (3 N und 4 N) wirken in dieselbe Richtung. Wie groß ist die Gesamtkraft?', a: ['7 N', '1 N', '12 N', '3,5 N'], e: 'Gleiche Richtung: Beträge addieren, 3 N + 4 N = 7 N.', src: 'OPAL Ph7 2'},
    {t: '2 Kraftpfeil und Kräfte addieren', d: 1, q: 'Zwei Kräfte (10 N und 6 N) wirken in entgegengesetzte Richtung. Wie groß ist die Gesamtkraft?', a: ['4 N', '16 N', '60 N', '8 N'], e: 'Entgegengesetzte Richtung: Beträge subtrahieren, 10 N − 6 N = 4 N – in Richtung der größeren Kraft.', src: 'OPAL Ph7 2'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 1, q: 'Welches Formelzeichen hat die Gewichtskraft?', a: ['$F_G$', '$G_F$', '$m_g$', '$N$'], e: 'Gewichtskraft = Kraft ($F$) mit Index G.', src: 'OPAL Ph7 3 Steckbrief'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 1, q: 'Welches Formelzeichen hat der Ortsfaktor?', a: ['$g$', '$G$', '$o$', '$F_O$'], e: 'Der Ortsfaktor heißt $g$ (kleines g).', src: 'OPAL Ph7 3 Steckbrief'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 1, q: 'In welcher Einheit gibt man den Ortsfaktor an?', a: ['N/kg', 'kg/N', 'N', 'kg'], e: 'Der Ortsfaktor sagt, wie viel Newton Gewichtskraft 1 kg hat.', src: 'OPAL Ph7 3 Steckbrief'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 1, q: 'Welche Größe ändert sich von der Erde zum Mond nicht?', a: ['Die Masse', 'Die Gewichtskraft', 'Der Ortsfaktor', 'Alle drei ändern sich'], e: 'Die Masse steckt im Körper. Gewichtskraft und Ortsfaktor hängen vom Himmelskörper ab.', src: 'OPAL Ph7 3'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 1, q: 'Welche Gewichtskraft hat ein Körper mit 2 kg auf der Erde?', a: ['20 N', '2 N', '0,2 N', '200 N'], e: '$F_G$ = 2 kg · 10 N/kg = 20 N.', src: 'OPAL Ph7 3'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 1, q: 'Ein Körper hat auf der Erde eine Gewichtskraft von 50 N. Welche Masse hat er?', a: ['5 kg', '500 kg', '50 kg', '0,5 kg'], e: '$m = {{F_G|g}}$ = {{50 N|10 N/kg}} = 5 kg.', src: 'OPAL Ph7 3'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 1, q: 'Welche Richtung hat die Gewichtskraft?', a: ['Zum Mittelpunkt des Himmelskörpers (nach unten)', 'Immer nach vorn', 'Nach oben', 'Nach links'], e: 'Die Gewichtskraft zeigt zum Erdmittelpunkt – senkrecht nach unten.', src: 'OPAL Ph7 3'},
    {t: '3 Gewichtskraft und Ortsfaktor', d: 1, q: 'Womit misst man die Gewichtskraft?', a: ['Mit dem Kraftmesser', 'Mit der Balkenwaage', 'Mit dem Lineal', 'Mit dem Messzylinder'], e: 'Der Kraftmesser zeigt die Gewichtskraft in Newton an.', src: 'OPAL Ph7 3'},
    {t: '4 Das Hooke’sche Gesetz', d: 1, q: 'Welches Formelzeichen hat die Verlängerung einer Feder?', a: ['$s$', '$l$', '$D$', '$v$'], e: 'Die Verlängerung heißt $s$.', src: 'OPAL Ph7 4 Steckbrief'},
    {t: '4 Das Hooke’sche Gesetz', d: 1, q: 'Welches Formelzeichen hat die Federkonstante?', a: ['$D$', '$F$', '$K$', '$s$'], e: 'Die Federkonstante heißt $D$.', src: 'OPAL Ph7 4 Steckbrief'},
    {t: '4 Das Hooke’sche Gesetz', d: 1, q: 'Wie lautet das Hooke’sche Gesetz?', a: ['$F = D · s$', '$F = D : s$', '$F = D + s$', '$F = s : D$'], e: 'Kraft = Federkonstante mal Verlängerung. Die Kraft ist proportional zur Verlängerung.', src: 'OPAL Ph7 4'},
    {t: '4 Das Hooke’sche Gesetz', d: 1, q: 'Was bedeutet „proportional“?', a: ['Doppelte Kraft – doppelte Verlängerung', 'Doppelte Kraft – halbe Verlängerung', 'Doppelte Kraft – gleiche Verlängerung', 'Doppelte Kraft – vier Mal so lang'], e: 'Proportional heißt: Wird die eine Größe doppelt so groß, wird es die andere auch.', src: 'OPAL Ph7 4'},
    {t: '4 Das Hooke’sche Gesetz', d: 1, q: 'Welche Einheit hat die Verlängerung $s$?', a: ['Zentimeter (cm)', 'Newton (N)', 'Kilogramm (kg)', 'N/cm'], e: 'Die Verlängerung ist eine Länge, also cm oder m.', src: 'OPAL Ph7 4'},
    {t: '5 Hebel und Hebelgesetz', d: 1, q: 'Welches Formelzeichen hat die Kraft an einem Hebel?', a: ['$F_1$ und $F_2$', '$m_1$ und $m_2$', '$l_1$ und $l_2$', '$D_1$ und $D_2$'], e: 'Die beiden Kräfte heißen $F_1$ und $F_2$, die Arme $l_1$ und $l_2$.', src: 'OPAL Ph7 5'},
    {t: '5 Hebel und Hebelgesetz', d: 1, q: 'Welches Formelzeichen haben die beiden Hebelarme?', a: ['$l_1$ und $l_2$', '$F_1$ und $F_2$', '$s_1$ und $s_2$', '$a$ und $b$'], e: 'Hebelarme heißen $l_1$ und $l_2$ (Länge).', src: 'OPAL Ph7 5'},
    {t: '5 Hebel und Hebelgesetz', d: 1, q: 'In welcher Einheit misst man einen Hebelarm?', a: ['Meter (m) oder Zentimeter (cm)', 'Newton (N)', 'Kilogramm (kg)', 'N/kg'], e: 'Ein Hebelarm ist ein Abstand – also eine Länge.', src: 'OPAL Ph7 5'},
    {t: '5 Hebel und Hebelgesetz', d: 1, q: 'Wo liegt der Drehpunkt beim Hebel?', a: ['Dort, wo sich der Hebel dreht', 'Immer am rechten Ende', 'Dort, wo die Last hängt', 'Immer in der Mitte'], e: 'Der Drehpunkt ist die Achse. Von ihm aus misst man die Arme.', src: 'OPAL Ph7 5'},
    {t: '6 Reibungskräfte', d: 1, q: 'Welches Formelzeichen hat die Reibungskraft?', a: ['$F_R$', '$R$', '$F_G$', '$R_F$'], e: 'Reibungskraft = Kraft ($F$) mit Index R.', src: 'OPAL Ph7 6'},
    {t: '6 Reibungskräfte', d: 1, q: 'In welcher Einheit gibt man die Reibungskraft an?', a: ['Newton (N)', 'Kilogramm (kg)', 'Meter (m)', 'N/kg'], e: 'Reibung ist eine Kraft, also in Newton.', src: 'OPAL Ph7 6'},
    {t: '6 Reibungskräfte', d: 1, q: 'Welche Reibungsarten kennen wir?', a: ['Haftreibung und Gleitreibung', 'Warmreibung und Kaltreibung', 'Luftreibung und Wasserreibung', 'Nur Gleitreibung'], e: 'Haftreibung hält einen ruhenden Körper fest, Gleitreibung bremst einen gleitenden.', src: 'OPAL Ph7 6'},
    {t: '6 Reibungskräfte', d: 1, q: 'Wie wirkt die Reibungskraft zur Bewegung?', a: ['Entgegengesetzt', 'In dieselbe Richtung', 'Senkrecht nach oben', 'Gar nicht'], e: 'Reibung bremst immer: Sie zeigt gegen die Bewegung.', src: 'OPAL Ph7 6'},
    {t: '6 Reibungskräfte', d: 1, q: 'Was ist üblicherweise größer: Haftreibung oder Gleitreibung?', a: ['Haftreibung', 'Gleitreibung', 'Beide sind immer gleich', 'Das hängt vom Wetter ab'], e: 'Eine ruhende Kiste loszuschieben ist schwerer als sie in Bewegung zu halten.', src: 'OPAL Ph7 6'},
    {t: '7 Magnete und magnetisches Feld', d: 1, q: 'Wie heißen die beiden Enden eines Magneten?', a: ['Nordpol und Südpol', 'Pluspol und Minuspol', 'Vorderpol und Hinterpol', 'Erdpol und Himmelspol'], e: 'Pluspol und Minuspol gibt es bei der Ladung, nicht beim Magneten.', src: 'OPAL Ph7 7'},
    {t: '7 Magnete und magnetisches Feld', d: 1, q: 'Was passiert bei zwei gleichnamigen Magnetpolen?', a: ['Sie stoßen sich ab.', 'Sie ziehen sich an.', 'Nichts.', 'Sie verschmelzen.'], e: 'Gleiche Pole stoßen sich ab, ungleiche ziehen sich an.', src: 'OPAL Ph7 7'},
    {t: '7 Magnete und magnetisches Feld', d: 1, q: 'Was passiert bei einem Nordpol und einem Südpol?', a: ['Sie ziehen sich an.', 'Sie stoßen sich ab.', 'Nichts.', 'Sie werden unmagnetisch.'], e: 'Ungleichnamige Pole ziehen sich an.', src: 'OPAL Ph7 7'},
    {t: '7 Magnete und magnetisches Feld', d: 1, q: 'Wie verlaufen magnetische Feldlinien außerhalb des Magneten?', a: ['Vom Nordpol zum Südpol', 'Vom Südpol zum Nordpol', 'Im Kreis um den Nordpol', 'Nur geradeaus'], e: 'Die Feldlinien zeigen: vom Nord- zum Südpol.', src: 'OPAL Ph7 7'},
    {t: '7 Magnete und magnetisches Feld', d: 1, q: 'Was geschieht, wenn man einen Stabmagneten in der Mitte zerbricht?', a: ['Zwei kleinere Magnete mit je Nord- und Südpol', 'Ein Nordmagnet und ein Südmagnet', 'Zwei unmagnetische Stücke', 'Ein starker und ein schwacher Magnet'], e: 'Einzelne Pole gibt es nicht – jedes Stück hat wieder zwei Pole.', src: 'OPAL Ph7 7'},
    {t: '8 Elektromagnete', d: 1, q: 'Wie kann man die Stärke eines Elektromagneten erhöhen?', a: ['Mehr Windungen oder mehr Strom', 'Weniger Windungen', 'Kupferkern statt Eisenkern', 'Die Spule kürzer abschneiden'], e: 'Mehr Windungen und größere Stromstärke verstärken das Feld.', src: 'OPAL Ph7 8'},
    {t: '8 Elektromagnete', d: 1, q: 'Welchen Vorteil hat ein Elektromagnet gegenüber einem Dauermagneten?', a: ['Man kann ihn an- und ausschalten.', 'Er braucht keinen Strom.', 'Er ist immer stärker.', 'Er hat nur einen Pol.'], e: 'Strom aus – Magnetismus (fast) weg: nützlich z. B. im Schrottplatzkran.', src: 'OPAL Ph7 8'},
    {t: '9 Elektrische Ladung und Feld', d: 1, q: 'Welche zwei Arten von Ladung gibt es?', a: ['Positiv und negativ', 'Nord und Süd', 'Warm und kalt', 'Schwer und leicht'], e: 'Nord und Süd gehören zum Magneten.', src: 'OPAL Ph7 9'},
    {t: '9 Elektrische Ladung und Feld', d: 1, q: 'Wie verhalten sich gleichnamige Ladungen?', a: ['Sie stoßen sich ab.', 'Sie ziehen sich an.', 'Sie bleiben unbeeinflusst.', 'Sie löschen sich aus.'], e: 'Gleiche Ladungen stoßen sich ab, ungleiche ziehen sich an.', src: 'OPAL Ph7 9'},
    {t: '9 Elektrische Ladung und Feld', d: 1, q: 'Welche Teilchen werden beim Reiben übertragen?', a: ['Elektronen', 'Protonen', 'Neutronen', 'Atomkerne'], e: 'Elektronen sind beweglich. Wer Elektronen aufnimmt, wird negativ.', src: 'OPAL Ph7 9'},
    {t: '9 Elektrische Ladung und Feld', d: 1, q: 'Was bedeutet „negativ geladen“?', a: ['Der Körper hat zu viele Elektronen.', 'Der Körper hat zu wenige Elektronen.', 'Der Körper ist kälter.', 'Der Körper ist schwerer.'], e: 'Überschuss an Elektronen = negativ geladen.', src: 'OPAL Ph7 9'}
  ]
};
